from archlib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
b = Board('Architecture_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('Components', ul('A part of the system you can name, run and replace: a service, a database, a queue, a client.', 'Plain: 196 × 68 with a flat icon. Illustrated: 232 × 96 with a name pill and a 64 px icon.', 'Name in the team\'s words (<i>Order service</i>). One detail line under it: the technology or the job.', 'The icon is chosen by the noun and comes from the shared sets. The tint groups by domain or owner, the same as in the other diagram types.')),
 card('Lines', ul('<b>Call:</b> ink, thin, arrow at the receiver. <b>Main path:</b> blue, thick, animated fast. <b>Event or message:</b> violet, thin, animated slowly. <b>Optional or copy:</b> dashed slate.', 'An arrow shows who starts the call, not which way data flows: a read is an arrow to the database.', 'Every line has a label: a protocol (HTTPS, SQL) or an action (charge, publish). Leave 90 px of line for it.', 'Routes are orthogonal with at most two bends. A fan of lines to one box uses separate entry points on its edge.', '<b>Frame edge:</b> a line that starts or ends on the edge of a frame means "from or to any part inside". Use it when many parts do the same thing (every client calls the gateway): draw one line, label it once.')),
 card('Zones', ul('A dashed, tinted frame with a dark pill label on its top left edge: region, private network, layer, third party.', 'Frames nest with 30 px between outer and inner edge. A part sits in the smallest frame that holds it.', 'Layer tints: clients blue, edge violet, services green, data amber, third party grey.', 'A line may cross a frame edge. That is where a boundary is crossed, so label it.')),
 card('Layers and direction', ul('Top to bottom for a request: clients, edge, services, data. Left to right for a short chain such as browser to database.', 'Parts in one layer share a centre line. Layers are 260 px apart in a plain diagram, 240 px with cards.', 'Third parties go in their own frame, to the right of the layer that calls them.', 'Do not mix both directions in one diagram.')),
 card('Spacing', ul('Parts in a row: at least 240 px between edges when the lines between them carry a label, 120 px when not.', 'A label never touches a frame edge or a box. If it does, widen the gap, not the label.', 'Eight to twelve parts is a good size. Past about fifteen, split by layer or domain.', 'A plain part keeps its size in every diagram. Never shrink one to make room.')),
 card('Animation', ul('Two tiers, no more. Blue main path: one route, the story of the diagram (a request, an order). Violet event stream: slow, thin.', 'Everything else is static. A second blue animated route cancels the effect.', 'Off when the viewer prefers reduced motion. In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('Two styles', ul('<b>Plain:</b> flat icon and text. Default; for design documents and reviews.', '<b>Illustrated:</b> cards with a large icon. For readers outside engineering or for a title slide.', 'Lines, labels, zones and tints are identical. Only the box size differs, so a diagram changes style by changing the layer spacing.')),
 card('Common patterns', ul('Six are drawn on the Patterns page: gateway, queue and worker, cache-aside, CDN, publish and subscribe, read replica.', 'A pattern is a small group of parts and lines. A plugin may add one to a diagram by name and then connect it.', 'Name the pattern in a note, not in the label of a part.')),
 card('Naming and detail', ul('Name parts by role, not by product: <i>Orders database</i>, with <i>PostgreSQL</i> in the detail line.', 'The same part keeps the same name in a flowchart, a sequence and an architecture.', 'A diagram shows what talks to what. Versions, sizes and settings belong in the text next to it.')),
 card('Reading it with other diagrams', ul('An architecture box can be a participant in a sequence or the database behind an ER diagram. Same name, same tint, same icon.', 'The blue path of an architecture is often one sequence diagram. Name it in a note so a reader can find it.', 'Not decided yet: linking a box to its ER or sequence page.')),
 card('Not covered yet', ul('Deployment detail such as nodes, pods and regions drawn to scale.', 'Trust boundaries and security zones as a separate frame kind.', 'Several lines between the same two parts with different labels.', 'These come later if the examples need them.')),
 card('What a plugin can rely on', ul('A part is: id, name, detail, icon, tone, layer and (optionally) zone.', 'A connection is: from, to (a part, or a zone for "any part inside"), kind (call, main, event, copy), label, and optional entry side.', 'A zone is: kind, label, tint and the parts it holds. Zones nest.', 'Layout comes from layers (rows) and slots (columns). The plugin places parts on a grid, then routes lines with the spacing rules above.', 'Anything not covered is left to the diagram author.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">Architecture · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">The conventions every architecture diagram follows, and that a plugin can rely on. Notation shows boxes, lines and frames, Patterns the common building blocks, and the examples show them together.</div></div>{grid}</div>')
print(save2(b))
